selector_to_html = {"a[href=\"#use-tle-struct\"]": "<h1 class=\"tippy-header\" style=\"margin-top: 0;\">Use TLE-Struct<a class=\"headerlink\" href=\"#use-tle-struct\" title=\"Link to this heading\">#</a></h1><p>This section introduces how to use TLE-Struct. TLE-Struct is available on trition_3.6.x branch.</p>", "a[href=\"#tle-gpu-set-layout\"]": "<h3 class=\"tippy-header\" style=\"margin-top: 0;\">tle.gpu.set_layout<a class=\"headerlink\" href=\"#tle-gpu-set-layout\" title=\"Link to this heading\">#</a></h3><p>Attach an explicit distributed layout to a block tensor value:</p>", "a[href=\"#tle-gpu-copy\"]": "<h3 class=\"tippy-header\" style=\"margin-top: 0;\">tle.gpu.copy<a class=\"headerlink\" href=\"#tle-gpu-copy\" title=\"Link to this heading\">#</a></h3><p>The following example demonstrates how to load a tile of data from the low-speed GMEM (Global Memory) into the high-speed on-chip SMEM.</p>", "a[href=\"#tle-dsa-alloc\"]": "<h3 class=\"tippy-header\" style=\"margin-top: 0;\">tle.dsa.alloc<a class=\"headerlink\" href=\"#tle-dsa-alloc\" title=\"Link to this heading\">#</a></h3><p>Signature: <code class=\"docutils literal notranslate\"><span class=\"pre\">tle.dsa.alloc(shape,</span> <span class=\"pre\">dtype,</span> <span class=\"pre\">mem_addr_space)</span></code>\nPurpose: Allocates a DSA local buffer in the specified memory address space.\nAddress spaces exposed by Huawei Ascend:</p>", "a[href=\"#tle-gpu-buffered-tensor-slot\"]": "<h3 class=\"tippy-header\" style=\"margin-top: 0;\">tle.gpu.buffered_tensor.slot<a class=\"headerlink\" href=\"#tle-gpu-buffered-tensor-slot\" title=\"Link to this heading\">#</a></h3><p>Select one stage from a staged shared-memory buffer:</p>", "a[href=\"#tle-dsa-add-tle-dsa-sub-tle-dsa-mul-tle-dsa-div-tle-dsa-max-and-tle-dsa-min\"]": "<h3 class=\"tippy-header\" style=\"margin-top: 0;\">tle.dsa.add, tle.dsa.sub, tle.dsa.mul, tle.dsa.div\uff0ctle.dsa.max\uff0cand tle.dsa.min<a class=\"headerlink\" href=\"#tle-dsa-add-tle-dsa-sub-tle-dsa-mul-tle-dsa-div-tle-dsa-max-and-tle-dsa-min\" title=\"Link to this heading\">#</a></h3><p>Built-in operators:\n<code class=\"docutils literal notranslate\"><span class=\"pre\">tle.dsa.add</span></code>\n<code class=\"docutils literal notranslate\"><span class=\"pre\">tle.dsa.sub</span></code>\n<code class=\"docutils literal notranslate\"><span class=\"pre\">tle.dsa.mul</span></code>\n<code class=\"docutils literal notranslate\"><span class=\"pre\">tle.dsa.div</span></code>\n<code class=\"docutils literal notranslate\"><span class=\"pre\">tle.dsa.max</span></code>\n<code class=\"docutils literal notranslate\"><span class=\"pre\">tle.dsa.min</span></code></p><p>General signature:<br/>\n<code class=\"docutils literal notranslate\"><span class=\"pre\">tle.dsa.(lhs,</span> <span class=\"pre\">rhs,</span> <span class=\"pre\">out)</span></code></p>", "a[href=\"#tle-gpu-barrier-api\"]": "<h2 class=\"tippy-header\" style=\"margin-top: 0;\">tle.gpu barrier API<a class=\"headerlink\" href=\"#tle-gpu-barrier-api\" title=\"Link to this heading\">#</a></h2><p>TLE GPU barriers express the synchronization needed by hand-written Hopper producer/consumer pipelines, including TMA completion barriers, empty/full mbarriers, and lightweight named barriers between warp groups.</p><p>API overview:</p>", "a[href=\"#tle-dsa-copy\"]": "<h3 class=\"tippy-header\" style=\"margin-top: 0;\">tle.dsa.copy<a class=\"headerlink\" href=\"#tle-dsa-copy\" title=\"Link to this heading\">#</a></h3><p>Signature: <code class=\"docutils literal notranslate\"><span class=\"pre\">tle.dsa.copy(src,</span> <span class=\"pre\">dst,</span> <span class=\"pre\">shape,</span> <span class=\"pre\">inter_no_alias=False)</span></code>\nPurpose: Performs explicit data movement (bidirectional) between GMEM pointers and DSA local buffers.</p>", "a[href=\"#loops-and-hints\"]": "<h2 class=\"tippy-header\" style=\"margin-top: 0;\">Loops and Hints<a class=\"headerlink\" href=\"#loops-and-hints\" title=\"Link to this heading\">#</a></h2><h3>tle.dsa.pipeline\uff0ctle.dsa.parallel\uff0cand tle.dsa.hint<a class=\"headerlink\" href=\"#tle-dsa-pipeline-tle-dsa-parallel-and-tle-dsa-hint\" title=\"Link to this heading\">#</a></h3><p>Loops and Hints API include:</p>", "a[href=\"#tle-dsa-pipeline-tle-dsa-parallel-and-tle-dsa-hint\"]": "<h3 class=\"tippy-header\" style=\"margin-top: 0;\">tle.dsa.pipeline\uff0ctle.dsa.parallel\uff0cand tle.dsa.hint<a class=\"headerlink\" href=\"#tle-dsa-pipeline-tle-dsa-parallel-and-tle-dsa-hint\" title=\"Link to this heading\">#</a></h3><p>Loops and Hints API include:</p>", "a[href=\"#tle-gpu-wgmma-and-tle-gpu-wgmma-wait\"]": "<h3 class=\"tippy-header\" style=\"margin-top: 0;\">tle.gpu.wgmma and tle.gpu.wgmma_wait<a class=\"headerlink\" href=\"#tle-gpu-wgmma-and-tle-gpu-wgmma-wait\" title=\"Link to this heading\">#</a></h3><p><code class=\"docutils literal notranslate\"><span class=\"pre\">tle.gpu.wgmma</span></code> issues an asynchronous Hopper WGMMA and returns an accumulator dependency value. Ordinary tensor ops, reductions, or stores must call <code class=\"docutils literal notranslate\"><span class=\"pre\">tle.gpu.wgmma_wait(...)</span></code> before consuming that accumulator.</p>", "a[href=\"#tle-dsa-local-ptr\"]": "<h3 class=\"tippy-header\" style=\"margin-top: 0;\">tle.dsa.local_ptr<a class=\"headerlink\" href=\"#tle-dsa-local-ptr\" title=\"Link to this heading\">#</a></h3><p>Semantics:<br/>\nThe pointer view model is identical to that of <code class=\"docutils literal notranslate\"><span class=\"pre\">tle.gpu.local_ptr</span></code> (same shape and indexing rules).<br/>\nIntended for DSA-local access patterns where explicit pointer materialization is required.</p>", "a[href=\"#tle-dsa-local-ptr-for-remote\"]": "<h3 class=\"tippy-header\" style=\"margin-top: 0;\">tle.dsa.local_ptr (for remote)<a class=\"headerlink\" href=\"#tle-dsa-local-ptr-for-remote\" title=\"Link to this heading\">#</a></h3>", "a[href=\"#tle-gpu-local-ptr-for-remote\"]": "<h3 class=\"tippy-header\" style=\"margin-top: 0;\">tle.gpu.local_ptr (for remote)<a class=\"headerlink\" href=\"#tle-gpu-local-ptr-for-remote\" title=\"Link to this heading\">#</a></h3><p>Read the remote SMEM tile on the neighboring shard.</p>", "a[href=\"#tle-gpu-memory-space\"]": "<h3 class=\"tippy-header\" style=\"margin-top: 0;\">tle.gpu.memory_space<a class=\"headerlink\" href=\"#tle-gpu-memory-space\" title=\"Link to this heading\">#</a></h3><p>Specify the memory_space for a given Tensor:</p>", "a[href=\"#tle-gpu-alloc\"]": "<h3 class=\"tippy-header\" style=\"margin-top: 0;\">tle.gpu.alloc<a class=\"headerlink\" href=\"#tle-gpu-alloc\" title=\"Link to this heading\">#</a></h3><p>The following example demonstrates how to reserve a block of memory in the GPU\u2019s high-speed on-chip  SMEM (Shared Memory) with dimensions <code class=\"docutils literal notranslate\"><span class=\"pre\">XBLOCK</span> <span class=\"pre\">*</span> <span class=\"pre\">YBLOCK</span></code> and data type <code class=\"docutils literal notranslate\"><span class=\"pre\">float32</span></code>.</p>", "a[href=\"#tle-gpu-local-ptr\"]": "<h3 class=\"tippy-header\" style=\"margin-top: 0;\">tle.gpu.local_ptr<a class=\"headerlink\" href=\"#tle-gpu-local-ptr\" title=\"Link to this heading\">#</a></h3><p>Obtain the memory pointer.</p>", "a[href=\"#tle-dsa-extract-slice-tle-dsa-insert-slice-tle-dsa-extract-element-and-tle-dsa-subview\"]": "<h3 class=\"tippy-header\" style=\"margin-top: 0;\">tle.dsa.extract_slice, tle.dsa.insert_slice, tle.dsa.extract_element, and tle.dsa.subview<a class=\"headerlink\" href=\"#tle-dsa-extract-slice-tle-dsa-insert-slice-tle-dsa-extract-element-and-tle-dsa-subview\" title=\"Link to this heading\">#</a></h3><p>Slicing and view API include:</p>", "a[href=\"#tle-gpu-warp-specialize\"]": "<h3 class=\"tippy-header\" style=\"margin-top: 0;\">tle.gpu.warp_specialize<a class=\"headerlink\" href=\"#tle-gpu-warp-specialize\" title=\"Link to this heading\">#</a></h3><p><code class=\"docutils literal notranslate\"><span class=\"pre\">tle.gpu.warp_specialize</span></code> is used to explicitly create a warp-specialized region within the same CTA, placing different JIT functions into different warp partitions. A typical use case is to separate tasks such as TMA/cp.async producers, WGMMA consumers, and epilogue/reduction, and pass shared-memory data between them via <code class=\"docutils literal notranslate\"><span class=\"pre\">tle.pipe</span></code> or other explicit synchronization primitives.</p>", "a[href=\"#dsa-memory-management-and-data-movement\"]": "<h2 class=\"tippy-header\" style=\"margin-top: 0;\">DSA memory management and data movement<a class=\"headerlink\" href=\"#dsa-memory-management-and-data-movement\" title=\"Link to this heading\">#</a></h2><h3>tle.dsa.alloc<a class=\"headerlink\" href=\"#tle-dsa-alloc\" title=\"Link to this heading\">#</a></h3><p>Signature: <code class=\"docutils literal notranslate\"><span class=\"pre\">tle.dsa.alloc(shape,</span> <span class=\"pre\">dtype,</span> <span class=\"pre\">mem_addr_space)</span></code>\nPurpose: Allocates a DSA local buffer in the specified memory address space.\nAddress spaces exposed by Huawei Ascend:</p>", "a[href=\"#execution-orchestration\"]": "<h2 class=\"tippy-header\" style=\"margin-top: 0;\">Execution orchestration<a class=\"headerlink\" href=\"#execution-orchestration\" title=\"Link to this heading\">#</a></h2><h3>tle.gpu.warp_specialize<a class=\"headerlink\" href=\"#tle-gpu-warp-specialize\" title=\"Link to this heading\">#</a></h3><p><code class=\"docutils literal notranslate\"><span class=\"pre\">tle.gpu.warp_specialize</span></code> is used to explicitly create a warp-specialized region within the same CTA, placing different JIT functions into different warp partitions. A typical use case is to separate tasks such as TMA/cp.async producers, WGMMA consumers, and epilogue/reduction, and pass shared-memory data between them via <code class=\"docutils literal notranslate\"><span class=\"pre\">tle.pipe</span></code> or other explicit synchronization primitives.</p>", "a[href=\"#gpu-memory-management\"]": "<h2 class=\"tippy-header\" style=\"margin-top: 0;\">GPU memory management<a class=\"headerlink\" href=\"#gpu-memory-management\" title=\"Link to this heading\">#</a></h2><p>You can use the following operations to manage the GPU\u2019s memory.</p>", "a[href=\"#slicing-and-view\"]": "<h2 class=\"tippy-header\" style=\"margin-top: 0;\">Slicing and view<a class=\"headerlink\" href=\"#slicing-and-view\" title=\"Link to this heading\">#</a></h2><h3>tle.dsa.extract_slice, tle.dsa.insert_slice, tle.dsa.extract_element, and tle.dsa.subview<a class=\"headerlink\" href=\"#tle-dsa-extract-slice-tle-dsa-insert-slice-tle-dsa-extract-element-and-tle-dsa-subview\" title=\"Link to this heading\">#</a></h3><p>Slicing and view API include:</p>", "a[href=\"#tle-gpu-buffered-tensor-reshape\"]": "<h3 class=\"tippy-header\" style=\"margin-top: 0;\">tle.gpu.buffered_tensor.reshape<a class=\"headerlink\" href=\"#tle-gpu-buffered-tensor-reshape\" title=\"Link to this heading\">#</a></h3><p>Create a shared-memory alias view with a different static shape:</p>", "a[href=\"#tle-dsa-to-tensor-and-tle-dsa-to-buffer\"]": "<h3 class=\"tippy-header\" style=\"margin-top: 0;\">tle.dsa.to_tensor and tle.dsa.to_buffer<a class=\"headerlink\" href=\"#tle-dsa-to-tensor-and-tle-dsa-to-buffer\" title=\"Link to this heading\">#</a></h3>", "a[href=\"#vector-operators-buffer-form\"]": "<h2 class=\"tippy-header\" style=\"margin-top: 0;\">Vector operators (Buffer form)<a class=\"headerlink\" href=\"#vector-operators-buffer-form\" title=\"Link to this heading\">#</a></h2><h3>tle.dsa.add, tle.dsa.sub, tle.dsa.mul, tle.dsa.div\uff0ctle.dsa.max\uff0cand tle.dsa.min<a class=\"headerlink\" href=\"#tle-dsa-add-tle-dsa-sub-tle-dsa-mul-tle-dsa-div-tle-dsa-max-and-tle-dsa-min\" title=\"Link to this heading\">#</a></h3><p>Built-in operators:\n<code class=\"docutils literal notranslate\"><span class=\"pre\">tle.dsa.add</span></code>\n<code class=\"docutils literal notranslate\"><span class=\"pre\">tle.dsa.sub</span></code>\n<code class=\"docutils literal notranslate\"><span class=\"pre\">tle.dsa.mul</span></code>\n<code class=\"docutils literal notranslate\"><span class=\"pre\">tle.dsa.div</span></code>\n<code class=\"docutils literal notranslate\"><span class=\"pre\">tle.dsa.max</span></code>\n<code class=\"docutils literal notranslate\"><span class=\"pre\">tle.dsa.min</span></code></p><p>General signature:<br/>\n<code class=\"docutils literal notranslate\"><span class=\"pre\">tle.dsa.(lhs,</span> <span class=\"pre\">rhs,</span> <span class=\"pre\">out)</span></code></p>"}
skip_classes = ["headerlink", "sd-stretched-link"]

window.onload = function () {
    for (const [select, tip_html] of Object.entries(selector_to_html)) {
        const links = document.querySelectorAll(` ${select}`);
        for (const link of links) {
            if (skip_classes.some(c => link.classList.contains(c))) {
                continue;
            }

            tippy(link, {
                content: tip_html,
                allowHTML: true,
                arrow: true,
                placement: 'auto-start', maxWidth: 500, interactive: false,

            });
        };
    };
    console.log("tippy tips loaded!");
};
